        : "";
    const povBlock = embodiedPov
        ? renderPromptParts(PROMPT_FRAGMENTS.storyDraftPromptFragment14.parts, [frame.povLifecycle?.viewerRole?.trim() || PROMPT_FRAGMENTS.storyDraftPromptFragment15.parts[0], POV_LIFECYCLE_STAGES.join(PROMPT_FRAGMENTS.storyDraftPromptFragment16.parts[0]), POV_CAMERA_ROLES.join(PROMPT_FRAGMENTS.storyDraftPromptFragment17.parts[0])])
