function storyEvidenceBlock(opts: StoryPlanOpts | undefined): StoryEvidenceRules {
    const evidence = opts?.research?.sources ?? [];
    if (!evidence.length) {
        return {
            block: "",
            hasEvidence: false,
            rule: PROMPT_FRAGMENTS.storyEvidenceBlockFragment0.parts[0],
        };
    }
    return {
        hasEvidence: true,
        block: storyEvidenceRecipe.render(evidence),
        rule: PROMPT_FRAGMENTS.storyEvidenceBlockFragment6.parts[0],
    };
}
