executablePrompt("prompt:sequence:storySequenceDirectionPrompt", PROMPT_FRAGMENTS.storySequenceDirectionPromptFragment0.parts, (input: {
    sections: readonly StoryPlanSection[];
    options: StoryDirectionOptions;
    correction: string | undefined;
}) => {
    const { sections, options, correction } = input;
    const beats = sections.map((section) => ({
        beatId: section.semanticBeatId,
