async function setupPrepare(context: PrepareContext): Promise<void> {
    const { job, args } = context;
    const { writerStyle, breath } = await workspaceBreath(job);
    context.writerStyle = writerStyle;
    context.breath = breath;
    context.brief = storyPromptLayers(args.brief || job.brief, job.direction);
    context.clarification = clarificationPlanningText(job);
    context.targetSec = Math.max(5, args.targetDurationSec ?? job.targetDurationSec ?? 60);
    if (context.targetSec !== job.targetDurationSec)
        job.targetDurationSec = context.targetSec;
    context.structure = resolveStoryStructure(args.structure, context.targetSec);
    context.density = storyDensityFor(context.structure, context.targetSec, breath);
    context.sectionCount = args.sectionCount ?? context.density.sectionCount;
}
