async function preserveGeneratedWork(context: PrepareContext): Promise<void> {
    const existing = context.inputs.plan!;
    const generated = existing.sections.filter((section) => section.status && section.status !== "draft");
    const ready = generated.filter((section) => section.status === "ready").length;
    const failed = generated.filter((section) => section.status === "failed").length;
    context.result = { kind: "note", note: `Story plan already in progress (${existing.sections.length} sections, ${ready} ready, ${failed} failed) — not re-planning, which would discard generated work. Use generate_story_assets to resume (it retries the failed/missing sections), or regenerate_section to redo one. To start over, clear the plan first.` };
}
