async function bindPlanningBrief(context: PrepareContext): Promise<void> {
    const { job, structure, targetSec, breath, brief, clarification } = context;
    context.wordBudget = structure === "narration_section" ? wordBudgetForTarget(targetSec, breath) : Math.round(targetSec * context.density!.wordsPerSec);
