async function framePreparedStory(context: PrepareContext): Promise<void> {
    const { job, args, sectionCount, wordBudget, structure, writerStyle, targetSec } = context;
    context.planOpts = await planOptsFor(job, args, { sectionCount, wordBudget, structure, writerStyle });
    context.shape = storyPlanShape(targetSec, context.planOpts);
    try {
        context.frame = await planStoryFrame(context.scriptingBrief, targetSec, context.shape.sectionCount, context.planOpts);
    }
    catch (err) {
        throw new Error(`Story planning failed: ${err instanceof Error ? err.message : String(err)}`);
    }
    context.grounded = context.frame.grounding.needed;
    context.research = matchingResearch(context.inputs.research, context.brief);
}
