    sectionCount: number;
    wordBudget: number;
    structure: StoryStructure;
    writerStyle: WriterStyleProfile | undefined;
}) {
    return {
        sectionCount: input.sectionCount, wordBudget: input.wordBudget, locked: await lockedConstraintsFor(job),
        language: job.language || undefined,
        structure: input.structure, planKind: normalizeVideoPlanKind(args.planKind), arc: args.arc, writerStyle: input.writerStyle,
        direction: await directionOptionsFor(job),
        requireGrounding: job.run?.pipeline?.profile.researchFirst,
    };
}
