export function interleaveSearchHits(groups: RawSearchHit[][]): RawSearchHit[] {
    const out: RawSearchHit[] = [];
    const max = groups.reduce((n, g) => Math.max(n, g.length), 0);
    for (let rank = 0; rank < max; rank++) {
        for (const group of groups)
            if (group[rank])
                out.push(group[rank]!);
    }
    return out;
}
