export function normalizeAndDedupe(hits: RawSearchHit[], cap: number = RESEARCH_CAPS.maxSources): Array<{
    url: string;
    title: string;
    snippet: string;
}> {
    const seen = new Set<string>();
    const out: Array<{
        url: string;
        title: string;
        snippet: string;
    }> = [];
    for (const h of hits) {
        const verdict = classifyUrl(h.url ?? "");
        if (!verdict.ok)
            continue;
        const key = dedupeKey(verdict.url);
        if (seen.has(key))
            continue;
        seen.add(key);
        out.push({
            url: verdict.url.toString(),
            title: clip(h.title || verdict.url.hostname, RESEARCH_CAPS.maxTitleChars),
            snippet: clip(h.snippet || "", RESEARCH_CAPS.maxExcerptChars),
        });
        if (out.length >= cap)
            break;
    }
    return out;
}
