function capValue(value: unknown, max = MAX_FIELD_CHARS): unknown {
    if (typeof value === "string")
        return value.length > max ? `${value.slice(0, max)}…[+${value.length - max}]` : value;
    if (Array.isArray(value))
        return value.slice(0, 50).map((v) => capValue(v, max));
    if (value && typeof value === "object") {
        const out: Record<string, unknown> = {};
        for (const [k, v] of entriesOfUnknown(value))
            out[k] = capValue(v, max);
        return out;
    }
    return value;
}
