export async function analyzeEvidenceDecisions(context: EvidenceDecisionContext): Promise<EvidenceDecisionOutcome> {
    if (analyzerOverride)
        return analyzerOverride(context);
    if (modelSeamsStubbed())
        return { kind: "none" };
    if (!context.sources.length)
        return { kind: "none" };
    let stdout: string;
    try {
        ({ stdout } = await runPrompt(evidenceDecisionPrompt(context), { timeoutMs: EVIDENCE_TIMEOUT_MS }));
    }
    catch (err) {
        return { kind: "fallback", reason: err instanceof Error ? err.message : String(err) };
    }
    let raw: unknown;
    try {
        raw = parseJson(stdout);
    }
    catch {
        return { kind: "fallback", reason: "the evidence analysis did not return readable JSON" };
    }
    const questions = raw && typeof raw === "object" && "questions" in raw ? raw.questions : undefined;
    if (Array.isArray(questions) && questions.length === 0)
        return { kind: "none" };
    const parsed = storyClarificationBatchSchema.safeParse(raw);
    if (!parsed.success)
        return { kind: "fallback", reason: "the evidence analysis returned a batch that does not fit the question contract" };
    if (parsed.data.stage !== POST_RESEARCH_CLARIFICATION_STAGE) {
        return { kind: "fallback", reason: "the evidence analysis returned a batch for the wrong stage" };
    }
    const bound = bindBatchToHeldSources(parsed.data, boundedEvidence(context.sources), context.priorDecisions);
    return bound ? { kind: "batch", batch: bound } : { kind: "none" };
}
