    const checkpoint = context.checkpoint!;
    const args = planStoryArgs.parse(checkpoint.args);
    const { writerStyle } = await workspaceBreath(job);
    const { brief, scriptingBrief, targetSec, structure, sectionCount, wordBudget, shape, frame, grounded } = checkpoint;
