async function draftStorySections(brief: string, frame: StoryFrame, slots: readonly StorySlot[], opts: StoryPlanOpts | undefined): Promise<StoryPlanSection[]> {
    const ask = async (subset: readonly StorySlot[]): Promise<{
        byIndex: Map<number, StoryPlanSection>;
        rejected: Map<number, string>;
    }> => {
        const raw = storyDrafterOverride
            ? await storyDrafterOverride(brief, subset, frame, opts)
            : parseJson((await runPrompt(storyDraftPrompt(brief, frame, subset, opts), { timeoutMs: STORY_DRAFT_TIMEOUT_MS })).stdout);
        const parsed = storyDraftSchema.parse(Array.isArray(raw) ? { sections: raw } : raw);
        const byIndex = new Map<number, StoryPlanSection>();
        const rejected = new Map<number, string>();
        for (const [order, section] of parsed.sections.entries()) {
            const slot = subset.find((candidate) => candidate.index === section.slot) ?? subset[order];
            if (!slot)
                continue;
            if (draftedSlot(section))
                byIndex.set(slot.index, section);
            else
                rejected.set(slot.index, section.narration.trim() ? "the drafter returned an empty visual prompt" : "the drafter returned an empty narration");
        }
        return { byIndex, rejected };
    };
    const drafted = new Map<number, StoryPlanSection>();
    const failure = new Map<number, string>();
    const describe = (error: unknown): string => {
        const message = error instanceof Error ? error.message : String(error);
        if (/timed out|ETIMEDOUT/i.test(message))
            return `the drafter timed out after ${Math.round(STORY_DRAFT_TIMEOUT_MS / 1000)}s`;
        try {
            const issues: unknown = JSON.parse(message);
            const first: unknown = Array.isArray(issues) ? issues[0] : undefined;
            if (first && typeof first === "object") {
                const path = "path" in first ? first.path : undefined;
                const detail = "message" in first && typeof first.message === "string" ? first.message.toLowerCase() : "was rejected";
                const field = Array.isArray(path) ? path.filter((part) => typeof part === "string").join(".") : "";
                return `the drafter returned an invalid section${field ? ` (${field}: ${detail})` : `: ${detail}`}`;
            }
        }
        catch { }
        return message;
    };
    try {
        const first = await ask(slots);
        for (const [index, section] of first.byIndex)
            drafted.set(index, section);
        for (const [index, why] of first.rejected)
            failure.set(index, why);
    }
    catch (error) {
        for (const slot of slots)
            failure.set(slot.index, describe(error));
    }
    for (const slot of slots) {
        if (drafted.has(slot.index))
            continue;
        try {
            const retry = await ask([slot]);
            const retried = retry.byIndex.get(slot.index);
            if (retried) {
                drafted.set(slot.index, retried);
                failure.delete(slot.index);
                continue;
            }
            failure.set(slot.index, retry.rejected.get(slot.index) ?? "the drafter returned no section for this slot");
        }
        catch (error) {
            failure.set(slot.index, describe(error));
        }
    }
    return slots.map((slot) => {
        const section = drafted.get(slot.index);
        return section ? withSlotStructure(slot, section) : undraftedSection(slot, failure.get(slot.index));
    });
}
