export async function directStorySequence(sections: readonly StoryPlanSection[], options: StoryDirectionOptions = {}): Promise<DirectedStorySections> {
    const unidentified = sections.filter((section) => !section.semanticBeatId);
    const undrafted = sections.filter((section) => section.needsDrafting);
    if (unidentified.length || undrafted.length) {
        const label = (section: StoryPlanSection, index: number): string => section.title?.trim() || `section ${index + 1}`;
        const errors: string[] = [];
        if (undrafted.length) {
            errors.push(`${undrafted.length} section(s) were never drafted and are still empty: ${undrafted.map((section) => label(section, sections.indexOf(section))).join(", ")}. Re-run planning, or write them by hand, then approve again.`);
        }
        if (unidentified.length) {
            errors.push(`${unidentified.length} section(s) have no stable beat id: ${unidentified.map((section) => label(section, sections.indexOf(section))).join(", ")}.`);
        }
        return { sections: [...sections], plannedReferences: options.authoritativeReferences ? [] : undefined, referenceAliases: options.authoritativeReferences ? [] : undefined, needsDirection: true, directionErrors: errors };
    }
    let failure = "sequence direction failed";
    for (let tries = 0; tries < 2; tries++) {
        try {
            const correction = tries > 0 ? failure : undefined;
            const raw = storySequenceDirectorOverride
                ? await storySequenceDirectorOverride(sections, options)
                : parseJson((await runPrompt(storySequenceDirectionPrompt(sections, options, correction), { timeoutMs: 300000 })).stdout);
            let direction: StorySequenceDirection = storySequenceDirectionSchema.parse(raw);
            if (options.authoritativeReferences) {
                if (!direction.plannedReferences || !direction.referenceAliases)
                    throw new Error("direction must return plannedReferences and referenceAliases");
                direction = collapseDirectionReferences(direction, options.roster ?? []);
            }
            const expected = sections.map((section) => section.semanticBeatId!);
            if (direction.beats.length !== expected.length || direction.beats.some((beat, index) => beat.beatId !== expected[index])) {
                throw new Error(`expected beat ids in order: ${expected.join(", ")}`);
            }
            const byId = new Map(direction.beats.map((beat) => [beat.beatId, beat.editorial]));
            const directed = sections.map((section) => {
                let editorial = byId.get(section.semanticBeatId!);
                if (options.allowInfographics === false && editorial?.presentation === "infographic") {
                    const { motionGraphic: _motionGraphic, ...rest } = editorial;
                    editorial = { ...rest, presentation: "explainer" };
                }
                return { ...section, editorial, motionGraphic: editorial?.motionGraphic };
            });
            const violations = storySequenceDirectionViolations(directed.map((section) => ({ id: section.semanticBeatId!, editorial: section.editorial })), { requireDirection: true });
            if (violations.length)
                throw new Error(storySequenceDirectionError(violations));
            if (options.authoritativeReferences) {
                const planned = direction.plannedReferences ?? [];
                const visualViolations = storyVisualDirectionViolations(directed.map((section) => ({
                    id: section.semanticBeatId!,
                    plannedShotCount: section.shots?.length ?? 1,
                    shots: section.editorial?.shots,
                })), {
                    roster: options.roster ?? [],
                    plannedKeys: planned.map((reference) => reference.key),
                    plannedRoles: Object.fromEntries(planned.map((reference) => [reference.key, reference.role])),
                    aliasedIdentities: (direction.referenceAliases ?? []).map((alias) => alias.ref),
                    requiredByBeat: Object.fromEntries(sections.map((section) => [section.semanticBeatId!, section.requiredReferences ?? []])),
                });
                if (visualViolations.length) {
                    const message = storyVisualDirectionError(visualViolations);
                    if (visualViolations.some((violation) => violation.invariant === "planned_product")) {
                        return { sections: [...sections], plannedReferences: direction.plannedReferences ?? [], referenceAliases: direction.referenceAliases ?? [], needsDirection: true, directionBlocked: true, directionErrors: [message] };
                    }
                    throw new Error(message);
                }
            }
            return { sections: directed, plannedReferences: direction.plannedReferences, referenceAliases: direction.referenceAliases };
        }
        catch (error) {
            failure = error instanceof Error ? error.message : String(error);
        }
    }
    return { sections: [...sections], plannedReferences: options.authoritativeReferences ? [] : undefined, referenceAliases: options.authoritativeReferences ? [] : undefined, needsDirection: true, directionErrors: [failure] };
}
