function validateQuotedEvidence(sourceEvidence: Array<{
    url: string;
    quote: string;
}> | undefined, evidence?: StoryResearchEvidence): Array<{
    url: string;
    quote: string;
}> {
    if (!evidence?.sources.length)
        return [];
    const byUrl = new Map(evidence.sources.map((s) => [s.url, normalizeEvidenceText(s.excerpt)]));
    const seen = new Set<string>();
    const valid: Array<{
        url: string;
        quote: string;
    }> = [];
    for (const item of sourceEvidence ?? []) {
        const quote = item.quote.trim();
        const normalized = normalizeEvidenceText(quote);
        const excerpt = byUrl.get(item.url);
        if (!excerpt || normalized.length < 20 || !excerpt.includes(normalized))
            continue;
        const key = `${item.url}\n${normalized}`;
        if (seen.has(key))
            continue;
        seen.add(key);
        valid.push({ url: item.url, quote });
    }
    return valid;
}
