function directedBibleEntries(plan: Pick<StoryPlanDraft, "sections" | "plannedReferences" | "referenceAliases">, roster: Awaited<ReturnType<typeof directionOptionsFor>>["roster"]): DirectedReferenceEntry[] {
    const aliases = new Map((plan.referenceAliases ?? []).map((entry) => [entry.ref, entry.aliases]));
    const planned = new Map((plan.plannedReferences ?? []).map((entry) => [entry.key, entry]));
    const entities = new Map(roster.map((entry) => [entry.id, entry]));
    const identities = new Set(plan.sections.flatMap((section) => section.editorial?.shots?.flatMap((shot) => shot.bindings.map(bindingIdentity)) ?? []));
    return [...identities].flatMap((identity): DirectedReferenceEntry[] => {
        if (identity.startsWith("entity:")) {
            const entity = entities.get(identity.slice("entity:".length));
            return entity ? [{ identity, role: entity.role, label: entity.label, description: entity.description, aliases: aliases.get(identity) }] : [];
        }
        const reference = planned.get(identity.slice("planned:".length));
        return reference ? [{ identity, role: reference.role, label: reference.label, description: reference.description, aliases: aliases.get(identity) }] : [];
    });
}
