function withPlannedReferences(bible: StoryBible, refs: readonly StoryPlannedReference[] | undefined): StoryBible {
    if (!refs?.length)
        return bible;
    const sameLabel = (a: string, b: string): boolean => a.trim().toLocaleLowerCase() === b.trim().toLocaleLowerCase();
    let subjects = [...bible.subjects];
    let locations = [...bible.locations];
    for (const ref of refs) {
        if (ref.role === "location") {
            const at = locations.findIndex((location) => sameLabel(location.label, ref.label));
            locations = at >= 0
                ? locations.map((location, index) => index === at
                    ? { ...location, descriptors: location.descriptors.length > 0 ? location.descriptors : [ref.description].filter(Boolean) }
                    : location)
                : [...locations, { id: slugId(ref.label, `location-${locations.length + 1}`), label: ref.label, descriptors: [ref.description].filter(Boolean) }];
            continue;
        }
        const at = subjects.findIndex((subject) => sameLabel(subject.label, ref.label));
        if (at >= 0) {
            subjects = subjects.map((subject, index) => index === at
                ? { ...subject, refKey: ref.key, descriptors: subject.descriptors.length > 0 ? subject.descriptors : [ref.description].filter(Boolean) }
                : subject);
            continue;
        }
        subjects = [...subjects, {
                id: slugId(ref.label, `subject-${subjects.length + 1}`),
                label: ref.label,
                aliases: [],
                descriptors: [ref.description].filter(Boolean),
                mustAvoid: [],
                refKey: ref.key,
            }];
    }
    return { ...bible, subjects, locations };
}
