async function persistPreparedStory(context: PrepareContext): Promise<void> {
    const { job, brief, grounded, targetSec, structure, wordBudget, research, evidence, visualStyle, bible, postResearch, writerStyle } = context;
    const checkpoint = context.checkpoint!;
    const plan = context.plan!;
    const sections = context.sections!;
    const unverified = !evidence && grounded;
    const clarificationProv = checkpoint.clarification ?? clarificationProvenance(job);
    const verifiedClarification = clarificationProv?.status === "answered"
        ? verifyStoryClarification(clarificationProv, { language: job.language || plan.language, planKind: plan.planKind })
        : clarificationProv;
    const contradictions = clarificationContradictions(verifiedClarification);
    const generationState = canonicalizeLegacyStoryPlan(sections);
    const directionFingerprint = plan.needsDirection ? undefined : await currentStoryDirectionFingerprint(job, sections);
    setStoryPlan(job, targetSec, sections, true, unverified, {
        planningBrief: brief, factual: grounded, researchKey: research ? fingerprintBrief(research.topic) : null, visualStyle, bible,
        clarification: verifiedClarification,
        postResearchClarification: postResearch,
        engagement: plan.engagement, planKind: plan.planKind, arc: plan.arc, frameDegraded: plan.frameDegraded, explainerContract: plan.explainerContract, povLifecycle: plan.povLifecycle, structure, language: job.language || plan.language, plannedReferences: plan.plannedReferences,
        referenceAliases: plan.referenceAliases,
        directionFingerprint,
        directionInputs: await storyDirectionInputsFor(job),
        needsDirection: plan.needsDirection, directionBlocked: plan.directionBlocked, directionErrors: plan.directionErrors,
        generationState,
    });
    await persist(job);
    const arcTitle = plan.arc ? ` · ${plan.arc}` : "";
    emitPlanTable(job, sections, structure === "narration_section"
        ? `Story plan${arcTitle} · ${sections.length} sections · ~${Math.round(targetSec / 60)} min`
        : `Story plan${arcTitle} · ${sections.length} beats · ~${targetSec}s`);
    job.events.push({ kind: "storyboard_patch" });
    const verification = planVerification(sections);
    const cited = verification.coverage?.verified ?? 0;
    const grounding = evidence
        ? ` ${verification.status?.toUpperCase() ?? "UNVERIFIED"}: ${research!.sources.length} source(s), ${cited}/${verification.coverage?.total ?? 0} factual sections citation-verified.`
        : unverified ? " UNVERIFIED DRAFT — no web sources were retrieved; claims are model recollection, not cited." : "";
    const unit = structure === "narration_section" ? "sections" : "beats";
    const craftNote = writerStyleWarning(sections, writerStyle);
    const arcViolations = storyArcCoverageViolations({
        arc: plan.arc,
        sections,
        engagement: plan.engagement,
    });
    const arcNote = plan.arc
        ? ` Arc: ${plan.arc}.${arcViolations.length ? ` Structure warnings — ${storyArcCoverageNote(arcViolations)}. Advisory only; approve when the pacing reads right to you.` : ""}`
        : "";
    const degradedNote = plan.frameDegraded ? " NOTE: the framing stage failed, so the arc and language came from defaults rather than from the brief." : "";
    const undrafted = sections.filter((section) => section.needsDrafting).length;
    const undraftedNote = undrafted ? ` ${undrafted} section(s) never drafted and are kept empty — re-run planning or edit them by hand.` : "";
    const clarificationNote = contradictions.length
        ? ` NOTE: the plan does not honor ${contradictions.length} clarification decision(s) — ${contradictions.map((decision) => `${decision.header}: asked for "${decision.answer}", plan has "${decision.planValue ?? "something else"}"`).join("; ")}.`
        : verifiedClarification?.status === "answered" && verifiedClarification.decisions.length
            ? ` Planning received ${verifiedClarification.decisions.length} clarification decision(s).`
            : "";
    const postResearchNote = postResearch?.status === "answered" && postResearch.decisions.length
        ? ` Drafted against ${postResearch.decisions.length} post-research decision(s) — ${postResearch.decisions.map((decision) => `${decision.header}: ${decision.answer}`).join("; ")}.`
        : "";
    clearPlanCheckpoint(job);
    context.outcome = { note: `Planned ${sections.length} ${unit} (~${wordBudget} words).${grounding}${arcNote}${degradedNote}${undraftedNote}${clarificationNote}${postResearchNote}${craftNote} Review the story plan, then approve to generate voiceover + images.` };
}
