export function setStoryPlan(job: AgentJob, targetSec: number, sections: StorySection[], emit = true, unverified?: boolean, context?: Omit<StoryPlanContext, "researchKey"> & {
    researchKey?: string | null;
}): void {
    const prev = jobArtifactsOfKind(job, storyPlanArtifact)[0]?.payload;
    const currentCitationModel = sections.some((s) => s.factual !== undefined || s.citationStatus !== undefined);
    const derived = planVerification(sections);
    const verificationStatus = currentCitationModel ? derived.status : (unverified ? "unverified" : prev?.verificationStatus);
    const carried = Object.fromEntries(CARRIED_CONTEXT.map((key) => [key, context?.[key] ?? prev?.[key]]));
    const payload: StoryPlanPayload = {
        ...carried,
        targetSec,
        sections,
        unverified: currentCitationModel ? verificationStatus === "unverified" : (verificationStatus ? verificationStatus === "unverified" : (unverified ?? prev?.unverified)),
        verificationStatus,
        citationCoverage: currentCitationModel ? derived.coverage : prev?.citationCoverage,
        researchKey: context ? (context.researchKey ?? undefined) : prev?.researchKey,
        planKind: context?.planKind ?? prev?.planKind ?? "story",
    };
    const inputRefs = context
        ? researchRefFor(job, payload.factual ? payload.researchKey : undefined)
        : jobArtifactsOfKind(job, storyPlanArtifact)[0]?.inputRefs ?? [];
    const artifact = putJobArtifact(job, storyPlanArtifact.kind, payload, currentProducer(job), { inputRefs });
