export function extractRequestedDurationSec(text: string): number | undefined {
    const minute = text.match(/\b(\d+(?:[.,]\d+)?|one|two|three|four|five|six|seven|eight|nine|ten|satu|dua|tiga|empat|lima|enam|tujuh|delapan|sembilan|sepuluh)\s*(?:menit|minute|minutes|min|mins|m)\b/i);
    if (minute) {
        const sec = Math.round(amount(minute[1]!) * 60);
        if (sec > 0)
            return sec;
    }
    const second = text.match(/\b(\d+(?:[.,]\d+)?|one|two|three|four|five|six|seven|eight|nine|ten|satu|dua|tiga|empat|lima|enam|tujuh|delapan|sembilan|sepuluh)\s*(?:detik|second|seconds|sec|secs|s)\b/i);
    if (second) {
        const sec = Math.round(amount(second[1]!));
        if (sec > 0)
            return sec;
    }
    return undefined;
}
