export async function decideGate(job: AgentJob, summary: string, label: string, answer: string | undefined): Promise<GateDecision> {
    const state = runState(job);
    if (state.approveAll)
        return "approve_all";
    if (answer === undefined) {
        await suspendForToolApproval(job, summary, label);
        return "suspend";
    }
    const choice = parsePipelineApprovalChoice(answer);
    if (choice === "approve_all")
        state.approveAll = true;
    return choice === "approve" || choice === "approve_all" ? choice : "reject";
}
