export function chatContextPrompt(context: ChatContextEnvelope | undefined): string {
    if (!context)
        return "";
    const focus = context.focus.entities.map((entity) => renderPromptParts(PROMPT_FRAGMENTS.chatContextPromptFragment0.parts, [entity.kind, entity.id])).join(PROMPT_FRAGMENTS.chatContextPromptFragment1.parts[0]);
    const decisions = context.memory.decisions.map((decision) => ({
        kind: decision.kind,
        question: decision.question,
        answer: decision.answer,
    }));
    return [
        PROMPT_FRAGMENTS.chatContextPromptFragment2.parts[0],
        renderPromptParts(PROMPT_FRAGMENTS.chatContextPromptFragment3.parts, [context.focus.source]),
        renderPromptParts(PROMPT_FRAGMENTS.chatContextPromptFragment4.parts, [focus || PROMPT_FRAGMENTS.chatContextPromptFragment5.parts[0]]),
        PROMPT_FRAGMENTS.chatContextPromptFragment6.parts[0],
        renderIndex(context.index),
        renderPromptParts(PROMPT_FRAGMENTS.chatContextPromptFragment7.parts, [JSON.stringify(context.detail)]),
        renderPromptParts(PROMPT_FRAGMENTS.chatContextPromptFragment8.parts, [JSON.stringify(decisions)]),
        renderPromptParts(PROMPT_FRAGMENTS.chatContextPromptFragment9.parts, [JSON.stringify(context.memory.unresolved.map((entry) => entry.question))]),
        renderPromptParts(PROMPT_FRAGMENTS.chatContextPromptFragment10.parts, [JSON.stringify(context.memory.recentTurns.map(({ role, text }) => ({ role, text })))]),
        ...(context.pendingAction ? [renderPromptParts(PROMPT_FRAGMENTS.chatContextPromptFragment11.parts, [JSON.stringify(context.pendingAction)])] : []),
        PROMPT_FRAGMENTS.chatContextPromptFragment12.parts[0],
    ].join(PROMPT_FRAGMENTS.chatContextPromptFragment13.parts[0]);
}
