        .filter(([, entries]) => entries.length > 0)
        .map(([group, entries]) => renderPromptParts(PROMPT_FRAGMENTS.renderIndexFragment0.parts, [group, renderIndexGroup(entries)]))
        .join(PROMPT_FRAGMENTS.renderIndexFragment1.parts[0]) || PROMPT_FRAGMENTS.renderIndexFragment2.parts[0];
}
