function renderIndexGroup(entries: ChatIndexEntry[]): string {
    const shown = entries.slice(0, MAX_INDEX_ENTRIES);
    const omitted = entries.length - shown.length;
    const body = JSON.stringify(shown);
    return omitted > 0 ? renderPromptParts(PROMPT_FRAGMENTS.renderIndexGroupFragment0.parts, [body, omitted]) : body;
}
