export function storyPlanStage(ctx: StoryPlanContext): Stage<AgentJob> {
    return {
        id: "plan",
        ...PLAN_CONTRACT,
        costsAssets: false,
        consumes: ["brief", "materials.story", "materials.voice", "materials.rules", "styleLock"],
        produce: async () => ({ operation: "create", targetsExisting: false, summary: `Draft ${ctx.label}`, payload: { kind: "gate" } }),
        commit: async (job): Promise<StageCommitResult> => {
            const { note, ok, suspended } = await emitToolCall(job, "plan_story", ctx.planArgs, (tcid) => runValidatedTool(job, "plan_story", ctx.planArgs, tcid));
            if (!ok)
                return { status: "failed", error: stageFailure("plan_failed", note) };
            if (suspended)
                return { status: "suspended", note };
            const planned = getStoryPlan(job);
            if (!planned)
                return { status: "failed", error: stageFailure("plan_failed", note) };
            const research = declaredArtifacts(job, PLAN_CONTRACT).find((artifact) => artifact.kind === researchBundleArtifact.kind);
            const sourceCount = payloadOfKind(research, researchBundleArtifact)?.sources.length ?? 0;
            if (planned.factual) {
                ctx.workflow.set("research", sourceCount ? "done" : "failed", {
                    reason: sourceCount ? `${sourceCount} source(s) retrieved` : "no sources retrieved — the plan is ungrounded",
                });
            }
            else {
                ctx.workflow.set("research", "skipped", { reason: "the brief needs no source grounding" });
            }
            ctx.workflow.set("plan", "done", { reason: note });
            ctx.workflow.set("approval", "running");
            job.events.push({ kind: "storyboard_patch" });
            job.run!.transcript += `\nPipeline plan: plan_story(${JSON.stringify(ctx.planArgs)}) -> ${note}`;
            return { status: "completed", note };
        },
    };
}
