export async function emitToolCall(job: AgentJob, tool: string, args: Record<string, unknown>, run: (toolCallId: string) => Promise<{
    note: string;
    thumbs?: string[];
    effect?: ToolEffect;
    suspended?: true;
}>): Promise<{
    note: string;
    ok: boolean;
    thumbs?: string[];
    suspended?: true;
}> {
    const startedAt = Date.now();
    const toolCallId = crypto.randomUUID();
    job.events.push({ kind: "tool_call_started", tool, args });
    let ok = true;
    let note: string;
    let thumbs: string[] | undefined;
    let effect: ToolEffect = "note";
    let suspended: true | undefined;
    try {
        const r = await run(toolCallId);
        note = r.note;
        thumbs = r.thumbs;
        effect = r.effect ?? "note";
        suspended = r.suspended;
    }
    catch (e) {
        ok = false;
        note = e instanceof Error ? e.message : String(e);
    }
    job.events.push({ kind: "tool_call_completed", tool, note, thumbs, effect: ok ? effect : "note", errorInfo: ok ? undefined : classifyAgentError(note) });
    await recordAgentToolEvent(job, { toolCallId, tool, args, note, ok, startedAt });
    return { note, ok, thumbs, suspended };
}
